param(
  [string]$TestDirectory = (Join-Path (Split-Path $PSScriptRoot -Parent) '.deps/queue-test'),
  [ValidateRange(2, 30)][int]$Rounds = 6,
  [ValidateRange(100000, 50000000)][int]$Messages = 2000000,
  [ValidateSet(8, 256)][int[]]$Capacities = @(8, 256)
)
$ErrorActionPreference = 'Stop'
$TestDirectory = (Resolve-Path -LiteralPath $TestDirectory).Path
$rows = [Collections.Generic.List[object]]::new()
$pairs = [Collections.Generic.List[object]]::new()
$summary = [Collections.Generic.List[object]]::new()

function Get-Median([double[]]$Values) {
  $ordered = @($Values | Sort-Object)
  $middle = [int][Math]::Floor($ordered.Count / 2)
  if ($ordered.Count % 2) { return $ordered[$middle] }
  return ($ordered[$middle - 1] + $ordered[$middle]) / 2
}
function Get-Distribution([double[]]$Values) {
  $measure = $Values | Measure-Object -Minimum -Maximum
  return [ordered]@{
    median = Get-Median $Values
    minimum = $measure.Minimum
    maximum = $measure.Maximum
    positive_pairs = @($Values | Where-Object { $_ -gt 0 }).Count
    pairs = $Values.Count
  }
}

$processorNames = @()
try { $processorNames = @(Get-CimInstance Win32_Processor | Select-Object -ExpandProperty Name) } catch { }
$hashes = [ordered]@{}
foreach ($variant in @('current', 'old-fence')) {
  $header = Join-Path $TestDirectory "include-$variant/util_atomiccircularqueue.h"
  if (Test-Path -LiteralPath $header) {
    $hashes[$variant] = (Get-FileHash -LiteralPath $header -Algorithm SHA256).Hash
  }
  foreach ($arch in @('x86', 'x64')) {
    $binary = Join-Path $TestDirectory "queue-benchmark-$variant-$arch.exe"
    if (!(Test-Path -LiteralPath $binary)) { throw "Missing benchmark executable: $binary" }
    $hashes["$variant-$arch-exe"] = (Get-FileHash -LiteralPath $binary -Algorithm SHA256).Hash
  }
}
[ordered]@{
  started_utc = [DateTime]::UtcNow.ToString('o')
  computer = $env:COMPUTERNAME
  operating_system = [Environment]::OSVersion.VersionString
  processor_names = $processorNames
  logical_processors = [Environment]::ProcessorCount
  messages_per_run = $Messages
  rounds = $Rounds
  capacities = $Capacities
  source_and_binary_sha256 = $hashes
  measurement = 'Cross-process producer push and consumer peek then pull; 64-byte validated payload; 25,000-message warmup. Latency samples every 256 messages measure enqueue attempt through successful peek, including queueing. CPU includes both measured processes; process CPU counters have OS timer granularity.'
  interpretation = 'Adjacent paired runs alternate current/old-fence order each round. Positive speedup/reduction favors current. No absolute performance threshold is used; compare paired distributions and run-to-run variation. This microbenchmark does not measure game FPS.'
} | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $TestDirectory 'benchmark-environment.json') -Encoding UTF8

foreach ($capacity in $Capacities) {
  foreach ($arch in @('x86', 'x64')) {
    $peer = if ($arch -eq 'x86') { 'x64' } else { 'x86' }
    $direction = "$arch-to-$peer"
    for ($round = 1; $round -le $Rounds; ++$round) {
      $variants = if ($round % 2) { @('current', 'old-fence') } else { @('old-fence', 'current') }
      $order = 0
      foreach ($variant in $variants) {
        ++$order
        $executable = Join-Path $TestDirectory "queue-benchmark-$variant-$arch.exe"
        $peerExecutable = Join-Path $TestDirectory "queue-benchmark-$variant-$peer.exe"
        $output = @(& $executable $peerExecutable $Messages $capacity)
        if ($LASTEXITCODE -ne 0) { throw "Queue benchmark failed: $direction $variant round $round" }
        $result = ($output -join "`n") | ConvertFrom-Json
        if ($result.messages -ne $Messages -or $result.capacity -ne $capacity) {
          throw 'Queue benchmark emitted an unexpected result'
        }
        $result | Add-Member -NotePropertyMembers @{
          direction = $direction; variant = $variant; round = $round; order = $order
        }
        $rows.Add($result)
        $rows | Export-Csv -LiteralPath (Join-Path $TestDirectory 'benchmark-results.csv') -NoTypeInformation -Encoding UTF8
        ConvertTo-Json -InputObject @($rows.ToArray()) -Depth 4 |
          Set-Content -LiteralPath (Join-Path $TestDirectory 'benchmark-results.json') -Encoding UTF8
        Write-Host ("{0}, capacity {1}, pair {2}, {3}: {4:N0} msg/s, {5:N1} CPU ns/msg, p99 {6:N0} ns" -f
          $direction, $capacity, $round, $variant, $result.throughput_per_second,
          $result.cpu_ns_per_message, $result.latency_p99_ns)
      }
      $current = $rows | Where-Object { $_.direction -eq $direction -and $_.capacity -eq $capacity -and $_.round -eq $round -and $_.variant -eq 'current' }
      $baseline = $rows | Where-Object { $_.direction -eq $direction -and $_.capacity -eq $capacity -and $_.round -eq $round -and $_.variant -eq 'old-fence' }
      $pairs.Add([pscustomobject]@{
        direction = $direction; capacity = $capacity; round = $round
        throughput_speedup_percent = 100 * ($current.throughput_per_second / $baseline.throughput_per_second - 1)
        cpu_reduction_percent = 100 * (1 - $current.cpu_ns_per_message / $baseline.cpu_ns_per_message)
        p50_reduction_percent = 100 * (1 - $current.latency_p50_ns / $baseline.latency_p50_ns)
        p95_reduction_percent = 100 * (1 - $current.latency_p95_ns / $baseline.latency_p95_ns)
        p99_reduction_percent = 100 * (1 - $current.latency_p99_ns / $baseline.latency_p99_ns)
      })
      $pairs | Export-Csv -LiteralPath (Join-Path $TestDirectory 'benchmark-pairs.csv') -NoTypeInformation -Encoding UTF8
    }
    $samples = @($pairs | Where-Object { $_.direction -eq $direction -and $_.capacity -eq $capacity })
    $summary.Add([pscustomobject]@{
      direction = $direction; capacity = $capacity
      throughput_speedup_percent = Get-Distribution @($samples.throughput_speedup_percent)
      cpu_reduction_percent = Get-Distribution @($samples.cpu_reduction_percent)
      p50_reduction_percent = Get-Distribution @($samples.p50_reduction_percent)
      p95_reduction_percent = Get-Distribution @($samples.p95_reduction_percent)
      p99_reduction_percent = Get-Distribution @($samples.p99_reduction_percent)
    })
    ConvertTo-Json -InputObject @($summary.ToArray()) -Depth 6 |
      Set-Content -LiteralPath (Join-Path $TestDirectory 'benchmark-summary.json') -Encoding UTF8
  }
}
Write-Host "Queue benchmark results saved to $TestDirectory/benchmark-results.csv and benchmark-summary.json"
